import json
from collections import defaultdict

def build_adjacency(cities, undirected_edges, directed_edges):
    adj = {c: set() for c in cities}
    for a, b in undirected_edges:
        adj[a].add(b)
        adj[b].add(a)
    for a, b in directed_edges:
        adj[a].add(b)
    return adj

def compute_day_ranges(order, durations):
    itinerary = []
    start_day = 1
    for city in order:
        end_day = start_day + durations[city] - 1
        itinerary.append((city, start_day, end_day))
        start_day = end_day  # overlap on flight day
    total_days = itinerary[-1][2] if itinerary else 0
    return itinerary, total_days

def windows_ok(itinerary, windows):
    # itinerary: list of (city, start, end)
    ranges = {city: (start, end) for city, start, end in itinerary}
    for city, (a, b) in windows.items():
        if city not in ranges:
            return False
        s, e = ranges[city]
        if not (s <= a and e >= b):
            return False
    return True

def search_itinerary(cities, durations, adj, windows, total_days):
    n = len(cities)
    # Quick sanity: sum(durations) - (n-1) must equal total_days
    if sum(durations[c] for c in cities) - (n - 1) != total_days:
        return None

    # Pre-calc ordered candidate lists for determinism
    neighbors_sorted = {c: sorted(adj[c]) for c in cities}
    cities_sorted = sorted(cities)

    # Helper to compute next start day given a partial path
    def next_start_day(path):
        return 1 + sum(durations[c] - 1 for c in path)

    # DFS with pruning for window start thresholds
    best_order = []

    def dfs(path, visited):
        nonlocal best_order
        k = len(path)

        # Prune if window mandatory cities cannot start on/before their needed start day
        ns = next_start_day(path)
        for city, (a, b) in windows.items():
            if city not in visited:
                # If we haven't scheduled this city yet, its start day will be >= ns.
                # If ns > a, it's impossible for this city to start at/before a, hence cannot cover [a,b].
                # This is a strong and safe prune in our case because durations(city) == (b-a+1),
                # so it must start exactly at a.
                if ns > a:
                    return False

        if k == n:
            itinerary, end_day = compute_day_ranges(path, durations)
            if end_day == total_days and windows_ok(itinerary, windows):
                best_order = path[:]
                return True
            return False

        if k == 0:
            candidates = cities_sorted
        else:
            candidates = [c for c in neighbors_sorted[path[-1]] if c not in visited]

        # Next start day for placing candidate
        ns = next_start_day(path)

        for c in candidates:
            # Window check for the city being placed now
            s = ns
            e = s + durations[c] - 1
            if c in windows:
                a, b = windows[c]
                if not (s <= a and e >= b):
                    continue

            visited.add(c)
            path.append(c)
            if dfs(path, visited):
                return True
            path.pop()
            visited.remove(c)
        return False

    dfs([], set())
    if not best_order:
        return None
    itinerary_tuples, _ = compute_day_ranges(best_order, durations)
    return itinerary_tuples

def main():
    # Input variables (trip constraints)
    total_days = 18
    cities = [
        "Reykjavik", "Riga", "Oslo", "Lyon", "Dubrovnik", "Madrid", "Warsaw", "London"
    ]
    durations = {
        "Reykjavik": 4,
        "Riga": 2,
        "Oslo": 3,
        "Lyon": 5,
        "Dubrovnik": 2,
        "Madrid": 2,
        "Warsaw": 4,
        "London": 3,
    }
    # Windows: must be in Riga between day 4 and 5; in Dubrovnik between day 7 and 8
    windows = {
        "Riga": (4, 5),
        "Dubrovnik": (7, 8),
    }

    # Direct flight edges
    undirected_edges = [
        ("Warsaw", "Reykjavik"),
        ("Oslo", "Madrid"),
        ("Warsaw", "Riga"),
        ("Lyon", "London"),
        ("Madrid", "London"),
        ("Warsaw", "London"),
        ("Warsaw", "Oslo"),
        ("Oslo", "Dubrovnik"),
        ("Oslo", "Reykjavik"),
        ("Riga", "Oslo"),
        ("Oslo", "Lyon"),
        ("Oslo", "London"),
        ("London", "Reykjavik"),
        ("Warsaw", "Madrid"),
        ("Madrid", "Lyon"),
        ("Dubrovnik", "Madrid"),
    ]
    directed_edges = [
        ("Reykjavik", "Madrid"),
    ]

    adj = build_adjacency(cities, undirected_edges, directed_edges)

    itinerary_tuples = search_itinerary(cities, durations, adj, windows, total_days)
    if itinerary_tuples is None:
        output = {"error": "No feasible itinerary found given the constraints."}
    else:
        itinerary = []
        for city, start, end in itinerary_tuples:
            itinerary.append({
                "day_range": f"Day {start}-{end}",
                "place": city
            })
        output = {"itinerary": itinerary}

    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
